local function MakeButton(name, label, icon, callback)  
local Btn = Instance.new("TextButton")  
Btn.Name = name  
Btn.Size = UDim2.new(BTN_WIDTH_SCALE, 0, 0, BTN_HEIGHT)  
Btn.Position = UDim2.new((1 - BTN_WIDTH_SCALE) / 2, 0, 0, 0)  
Btn.BackgroundColor3 = C_BTN  
Btn.TextColor3 = C_TEXT  
Btn.Font = Enum.Font.GothamSemibold  
Btn.TextSize = 13  
Btn.TextXAlignment = Enum.TextXAlignment.Left  
Btn.Text = ("%s  %s"):format(icon, label)  
Btn.AutoButtonColor = false  
Btn.LayoutOrder = 0  
Btn.Parent = ScrollingFrame

Btn.MouseEnter:Connect(function() Btn.BackgroundColor3 = C_BTN_HV end)  
Btn.MouseLeave:Connect(function() Btn.BackgroundColor3 = C_BTN end)  
Btn.MouseButton1Click:Connect(function()  
if callback then callback() end  
end)

return Btn  
end

local function GetSyncRemote()  
local tool  
for _, v in game.Players.LocalPlayer:GetDescendants() do  
if v.Name == "SyncAPI" then tool = v.Parent; break end  
end  
if not tool then  
for _, v in game.ReplicatedStorage:GetDescendants() do  
if v.Name == "SyncAPI" then tool = v.Parent; break end  
end  
end  
if not tool or not tool:FindFirstChild("SyncAPI") then return nil end  
return tool.SyncAPI.ServerEndpoint  
end

local function RemoteInvoke(remote, args)  
remote:InvokeServer(unpack(args))  
end

local function GetHDAdminRemote()  
return game:GetService("ReplicatedStorage")  
:WaitForChild("HDAdminHDClient").Signals.RequestCommandSilent  
end

